impl Solution {
    pub fn split_array(nums: Vec<i32>, k: i32) -> i32 {
        let k = k as usize;
        let n = nums.len();

        // The minimum largest sum is at least the max element (since each subarray must contain at least one element)
        let mut left = *nums.iter().max().unwrap();
        // The maximum largest sum is the sum of all elements (one subarray)
        let mut right: i32 = nums.iter().sum();

        // Helper function to check if we can split nums into <= k subarrays with max sum <= mid
        fn can_split(nums: &[i32], k: usize, mid: i32) -> bool {
            let mut count = 1;
            let mut current_sum = 0;
            for &num in nums {
                if current_sum + num > mid {
                    count += 1;
                    current_sum = num;
                    if count > k {
                        return false;
                    }
                } else {
                    current_sum += num;
                }
            }
            true
        }

        while left < right {
            let mid = left + (right - left) / 2;
            if can_split(&nums, k, mid) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        left
    }
}

